after(function () {
    // Print summary
    var hex02 =
      "0x" + results.result02.toString(16).toUpperCase().padStart(2, "0");
    var hex03 =
      "0x" + results.result03.toString(16).toUpperCase().padStart(2, "0");
    console.log("");
    console.log(
      "    nestest results: byte 0x02 = " + hex02 + ", byte 0x03 = " + hex03,
    );
    if (results.result02 === 0 && results.result03 === 0) {
      console.log("    All tests passed!");
    } else {
      if (results.result02 !== 0) {
        console.log(
          "    Last failure (page 1): " +
            describeError("0x02", results.result02, ERRORS_02),
        );
      }
      if (results.result02 === 0 && results.result03 !== 0) {
        console.log(
          "    Last failure (page 2): " +
            describeError("0x03", results.result03, ERRORS_03),
        );
      }
    }
  })

before(function (done) {
    fs.readFile("roms/AccuracyCoin/AccuracyCoin.nes", function (err, data) {
      if (err) return done(err);
      run = runAccuracyCoin(data.toString("binary"));
      done();
    });
  })

after(function () {
    if (!run) return;
    // Print summary
    var pass = 0;
    var fail = 0;
    var notRun = 0;
    var failures = [];

    ALL_TESTS.forEach(function (test) {
      var result = run.results[test.addr];
      if (result === 0x01) {
        pass++;
      } else if (result === 0x00 || result === 0xff) {
        notRun++;
      } else {
        fail++;
        failures.push(
          "    " + test.page + " / " + test.name + ": " + formatResult(result),
        );
      }
    });

    console.log("");
    console.log(
      "    AccuracyCoin: " +
        pass +
        " passed, " +
        fail +
        " failed, " +
        notRun +
        " not run (" +
        run.framesRun +
        " frames)",
    );
    if (failures.length > 0) {
      console.log("    Failures:");
      failures.forEach(function (f) {
        console.log(f);
      });
    }
  })

