beforeEach(function() {
    // Create a fresh Express app for each test
    app = express();
    app.use(bodyParser.json());
    app.use(bodyParser.urlencoded({ extended: true }));
    app.use(session({
      name: 'session',
      keys: ['test-key'],
      maxAge: 24 * 60 * 60 * 1000
    }));

    // Mock the Dropbox plugin
    mockDropbox = {
      isConfigured: true,
      config: {
        app_key: 'test_key',
        app_secret: 'test_secret'
      },
      getAuthUrl: sinon.stub(),
      getRemoteAccessToken: sinon.stub(),
      getAccountInfo: sinon.stub(),
      searchForMdFiles: sinon.stub(),
      fetchDropboxFile: sinon.stub(),
      saveFileToDropbox: sinon.stub(),
      saveImageToDropbox: sinon.stub()
    };

    // Load server routes with mocked Dropbox plugin
    dropboxServer = proxyquire('../../../plugins/dropbox/server.js', {
      './dropbox.js': { Dropbox: mockDropbox }
    });

    app.use('/', dropboxServer);
  })

before(async function () {
    // Workspace chrome (sidebar toggle) proves both mount and restore.
    // (The smoke spec's `.animate-fade-in` wrapper no longer exists in App.tsx.)
    workspaceRestored = await $('button[aria-label="Hide sidebar"]')
      .waitForExist({ timeout: 15_000 })
      .catch(() => false);
  })

before(async function () {
    workspaceRestored = await $('button[aria-label="Hide sidebar"]')
      .waitForExist({ timeout: 15_000 })
      .catch(() => false);
    if (!workspaceRestored) return;

    const recents = await invoke("get_recent_workspaces", {});
    const root = recents.ok && Array.isArray(recents.value) ? recents.value[0] : null;
    ok(root, "no workspace root to seed the math document into");

    filePath = `${root}/${FILE_STEM}.md`;
    const wrote = await invoke("write_file", { path: filePath, content: DOC });
    ok(wrote.ok, `failed to seed ${filePath}: ${wrote.error}`);
  })

after(async function () {
    if (filePath) await invoke("delete_entry", { path: filePath });
  })

before(async function () {
    const workspaceRestored = await $('button[aria-label="Hide sidebar"]')
      .waitForExist({ timeout: 3_000 })
      .catch(() => false);
    if (!workspaceRestored) {
      await invoke("open_workspace", { path: E2E_WORKSPACE });
    }
    await waitForMount();
    await resetVisibilitySettings();
    await browser.refresh();
    await waitForMount();
  })

